namespace sv_bad8cde906a94aaa8840db2897d42797.Client;

public sealed class UserInfo
{
    public required string Email { get; init; }
    public required string[] Roles { get; init; }
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_bad8cde906a94aaa8840db2897d42797.Client;

/// <summary>
/// Reads the persisted user info that was serialized by the server during
/// static/server rendering and re-hydrates it into an AuthenticationState
/// so that identity survives the switch to WebAssembly.
/// </summary>
public sealed class ClientAuthenticationStateProvider : AuthenticationStateProvider
{
    private static readonly Task<AuthenticationState> _unauthenticated =
        Task.FromResult(new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity())));

    private readonly Task<AuthenticationState> _authenticationState;

    public ClientAuthenticationStateProvider(PersistentComponentState persistentState)
    {
        if (persistentState.TryTakeFromJson<UserInfo>(nameof(UserInfo), out var userInfo) && userInfo is not null)
        {
            var claims = new List<Claim>
            {
                new(ClaimTypes.Name, userInfo.Email),
                new(ClaimTypes.Email, userInfo.Email),
            };

            foreach (var role in userInfo.Roles)
            {
                claims.Add(new Claim(ClaimTypes.Role, role));
            }

            var identity = new ClaimsIdentity(claims, authenticationType: "PersistentAuth");
            _authenticationState = Task.FromResult(new AuthenticationState(new ClaimsPrincipal(identity)));
        }
        else
        {
            _authenticationState = _unauthenticated;
        }
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync() => _authenticationState;
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Server;
using Microsoft.AspNetCore.Components.Web;
using sv_bad8cde906a94aaa8840db2897d42797.Client;

namespace sv_bad8cde906a94aaa8840db2897d42797;

/// <summary>
/// Provides a hardcoded authenticated user on the server and persists the
/// identity into PersistentComponentState so the WebAssembly runtime can
/// pick it up after the handoff.
/// </summary>
public sealed class ServerAuthenticationStateProvider : ServerAuthenticationStateProvider<UserInfo>
{
    private static readonly AuthenticationState _authenticatedState;

    static ServerAuthenticationStateProvider()
    {
        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, "bob@example.com"),
            new(ClaimTypes.Email, "bob@example.com"),
            new(ClaimTypes.Role, "User"),
            new(ClaimTypes.Role, "Editor"),
        };

        var identity = new ClaimsIdentity(claims, authenticationType: "Hardcoded");
        _authenticatedState = new AuthenticationState(new ClaimsPrincipal(identity));
    }

    protected override Task<AuthenticationState> GetAuthenticationStateAsync()
        => Task.FromResult(_authenticatedState);

    protected override UserInfo MapToClientModel(AuthenticationState authenticationState)
    {
        var principal = authenticationState.User;
        return new UserInfo
        {
            Email = principal.FindFirstValue(ClaimTypes.Email)!,
            Roles = principal.FindAll(ClaimTypes.Role).Select(c => c.Value).ToArray(),
        };
    }
}

@page "/profile"
@rendermode InteractiveAuto
@using Microsoft.AspNetCore.Components.Authorization
@inject AuthenticationStateProvider AuthStateProvider

<PageTitle>Profile</PageTitle>

<h1>Profile</h1>

@if (_name is not null)
{
    <p><strong>Name:</strong> @_name</p>
    <h4>Roles</h4>
    <ul>
        @foreach (var role in _roles)
        {
            <li>@role</li>
        }
    </ul>
}
else
{
    <p>Not authenticated.</p>
}

@code {
    private string? _name;
    private string[] _roles = [];

    protected override async Task OnInitializedAsync()
    {
        var state = await AuthStateProvider.GetAuthenticationStateAsync();
        var user = state.User;

        if (user.Identity?.IsAuthenticated == true)
        {
            _name = user.Identity.Name;
            _roles = user.FindAll(System.Security.Claims.ClaimTypes.Role)
                         .Select(c => c.Value)
                         .ToArray();
        }
    }
}

